-- Sprint 1c (D-041): the About page's own phone image (portrait) — the same desk scene as the wide one, composed for a tall screen.
-- Generated by scripts/build-hero-photos.mjs --replace; the encoded image(s) are in design/hero/. The slot's current
-- photo is superseded (BR-1.17: kept, never altered or deleted) and the new one becomes current — the owner can replace
-- it in Admin → Photos at any time. Additive only.


UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-about-mobile' AND "supersededAt" IS NULL AND "sha256" <> '6faeafc4b8541d13e0adfa135174c507e2b85fd553dff8f37c0dad082eb0b0bf';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-about-mobile', 'A decorative image behind the top of the About page on phones', 'image/webp', 1024, 1536, 59732, '6faeafc4b8541d13e0adfa135174c507e2b85fd553dff8f37c0dad082eb0b0bf', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-about-mobile' AND "supersededAt" IS NULL);
